    {
      "id": "sentiment-3",
      "input": "This TUI is amazing!",
      "context": "Analyze the sentiment of this sentence. Determine if it expresses positive, negative, or neutral sentiment and provide reasoning for your assessment."
    }
  ],
  "totalItems": 3
}
